package net.civeira.phylax.feature.observe.observedissue.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssue;
import net.civeira.phylax.feature.observe.observedissue.domain.valueobject.UsersSketchVO;

class UsersSketchValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of users sketch of observed issue")
  void test_users_sketch_value_holder_assign_plain_value() {
    Object holder = new Object();
    UsersSketchValueHolder<Object> value = new UsersSketchValueHolder<>(holder);
    Assertions.assertSame(holder, value.usersSketch("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getUsersSketchValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getUsersSketch().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.usersSketchNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getUsersSketchValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getUsersSketch().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of users sketch of observed issue")
  void test_users_sketch_value_holder_assign_value_object() {
    Object holder = new Object();
    UsersSketchValueHolder<Object> value = new UsersSketchValueHolder<>(holder);
    UsersSketchVO vo = UsersSketchVO.from("one");
    Assertions.assertFalse(value.getUsersSketchValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.usersSketch(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getUsersSketchValue().orElseThrow());
    Assertions.assertSame(holder, value.usersSketch(Optional.empty()));
    Assertions.assertFalse(value.getUsersSketchValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.usersSketch(Optional.of(vo)));
    Assertions.assertSame(vo, value.getUsersSketchValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of users sketch of observed issue against the original")
  void test_users_sketch_value_holder_read() {
    Object holder = new Object();
    UsersSketchValueHolder<Object> value = new UsersSketchValueHolder<>(holder);
    UsersSketchVO vo = UsersSketchVO.from("one");
    UsersSketchVO other = UsersSketchVO.from("one");
    ObservedIssue original = Mockito.mock(ObservedIssue.class);
    Mockito.when(original.getUsersSketchValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readUsersSketch(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readUsersSketch(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.usersSketch(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readUsersSketch(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readUsersSketch(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of users sketch of observed issue")
  void test_users_sketch_value_holder_unset() {
    Object holder = new Object();
    UsersSketchValueHolder<Object> value = new UsersSketchValueHolder<>(holder);
    UsersSketchVO vo = UsersSketchVO.from("one");
    value.usersSketch(vo);
    Assertions.assertSame(holder, value.unsetUsersSketchIfMatches("usersSketch_other"));
    Assertions.assertTrue(value.getUsersSketchValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetUsersSketchIfMatches("usersSketch"));
    Assertions.assertFalse(value.getUsersSketchValue().isPresent(),
        "The field name must clear the value");
    value.usersSketch(vo);
    Assertions.assertSame(holder, value.unsetUsersSketch());
    Assertions.assertFalse(value.getUsersSketchValue().isPresent(), "Unset must clear the value");
  }
}
